  interface

    !---------------------------------------------
    ! rocblas_create_handle
    !---------------------------------------------
    !>  \brief Create handle.
    function rocblas_create_handle(handle) &
       result(create_handle) &
       bind(C, name="rocblas_create_handle")
       import :: c_ptr, rocblas_status_success
       type(c_ptr) :: handle
       integer(kind(rocblas_status_success)) :: create_handle
    end function rocblas_create_handle

    !---------------------------------------------
    ! rocblas_destroy_handle
    !---------------------------------------------
    !>  \brief Destroy handle.
    function rocblas_destroy_handle(handle) &
       result(destroy_handle) &
       bind(C, name="rocblas_destroy_handle")
       import :: c_ptr, rocblas_status_success
       type(c_ptr), value :: handle
       integer(kind(rocblas_status_success)) :: destroy_handle
    end function rocblas_destroy_handle

    !---------------------------------------------
    ! rocblas_set_stream
