       import :: c_ptr, rocblas_status_success
       type(c_ptr), value :: handle
       type(c_ptr), value :: stream
       integer(kind(rocblas_status_success)) :: set_stream
    end function rocblas_set_stream

    !---------------------------------------------
    ! rocblas_get_stream
    !---------------------------------------------
    !>  \brief Get stream [0] from handle.
    function rocblas_get_stream(handle, stream) &
