    end function rocblas_get_pointer_mode

    !---------------------------------------------
    ! rocblas_set_atomics_mode
    !---------------------------------------------
    !>  \brief Set ``rocblas_atomics_mode``
    !>   \details
    !>   Some rocBLAS functions have implementations which use atomic operations to increase
    !>   performance.
    !>   By using atomic operations, results are not guaranteed to be identical between multiple
    !>   runs.
    !>   Results are accurate with or without atomic operations. Atomic operations in rocBLAS are
    !>   turned
    !>   off by default. They can be turned on or off on a per-handle basis by calling
    !>   ``rocblas_set_atomics_mode``.
    function rocblas_set_atomics_mode(handle, atomics_mode) &
       result(set_atomics_mode) &
       bind(C, name="rocblas_set_atomics_mode")
       import :: c_ptr, rocblas_atomics_not_allowed, rocblas_status_success
       type(c_ptr), value :: handle
       integer(kind(rocblas_atomics_not_allowed)), value :: atomics_mode
       integer(kind(rocblas_status_success)) :: set_atomics_mode
    end function rocblas_set_atomics_mode

    !---------------------------------------------
    ! rocblas_get_atomics_mode
    !---------------------------------------------
    !>  \brief Get ``rocblas_atomics_mode``.
    function rocblas_get_atomics_mode(handle, atomics_mode) &
       result(get_atomics_mode) &
       bind(C, name="rocblas_get_atomics_mode")
       import :: c_ptr, rocblas_status_success
       type(c_ptr), value :: handle
       type(c_ptr), value :: atomics_mode
       integer(kind(rocblas_status_success)) :: get_atomics_mode
    end function rocblas_get_atomics_mode

    !---------------------------------------------
    ! rocblas_set_batch_alpha_stride
    !---------------------------------------------
    !>  \brief Set alpha stride for limited set of batched and strided_batched functions to specify
    !>  the stride for alpha between successive batch elements.
    !> Only applies to rocblas_pointer_mode_device and thus device side allocations.
    !> It enables interpretation of the alpha pointer for both batched and strided_batched functions
    !> as a pointer to a vector of values.
    !> Default value is 0 which treats it as a pointer to a single scalar. Support is denoted with
    !> specific function documentation.
    !> Warning this is a modal like state in the handle. Restore to value 0 if no longer applicable
    !> to later function calls.
    function rocblas_set_batch_alpha_stride(handle, alpha_stride) &
       result(set_batch_alpha_stride) &
       bind(C, name="rocblas_set_batch_alpha_stride")
       import :: c_ptr, c_int64_t, rocblas_status_success
       type(c_ptr), value :: handle
       integer(c_int64_t), value :: alpha_stride
       integer(kind(rocblas_status_success)) :: set_batch_alpha_stride
    end function rocblas_set_batch_alpha_stride

    !---------------------------------------------
    ! rocblas_get_batch_alpha_stride
    !---------------------------------------------
    !>  \brief Get batch alpha stride from the handle.
    function rocblas_get_batch_alpha_stride(handle, alpha_stride) &
       result(get_batch_alpha_stride) &
       bind(C, name="rocblas_get_batch_alpha_stride")
       import :: c_ptr, rocblas_status_success
       type(c_ptr), value :: handle
       type(c_ptr), value :: alpha_stride
       integer(kind(rocblas_status_success)) :: get_batch_alpha_stride
    end function rocblas_get_batch_alpha_stride

    !---------------------------------------------
    ! rocblas_set_batch_beta_stride
    !---------------------------------------------
    !>  \brief Set beta stride for limited set of batched and strided_batched functions to specify
    !>  the stride for beta between successive batch elements.
    !> Only applies to rocblas_pointer_mode_device and thus device side allocations.
    !> It enables interpretation of the beta pointer for both batched and strided_batched functions
    !> as a pointer to a vector of values.
    !> Default value is 0 which treats it as a pointer to a single scalar. Support is denoted with
    !> specific function documentation.
    !> Warning this is a modal like state in the handle. Restore to value 0 if no longer applicable
    !> to later function calls.
    function rocblas_set_batch_beta_stride(handle, beta_stride) &
       result(set_batch_beta_stride) &
       bind(C, name="rocblas_set_batch_beta_stride")
       import :: c_ptr, c_int64_t, rocblas_status_success
       type(c_ptr), value :: handle
       integer(c_int64_t), value :: beta_stride
       integer(kind(rocblas_status_success)) :: set_batch_beta_stride
    end function rocblas_set_batch_beta_stride

    !---------------------------------------------
    ! rocblas_get_batch_beta_stride
    !---------------------------------------------
    !>  \brief Get batch beta stride from the handle.
    function rocblas_get_batch_beta_stride(handle, beta_stride) &
       result(get_batch_beta_stride) &
       bind(C, name="rocblas_get_batch_beta_stride")
       import :: c_ptr, rocblas_status_success
       type(c_ptr), value :: handle
       type(c_ptr), value :: beta_stride
       integer(kind(rocblas_status_success)) :: get_batch_beta_stride
    end function rocblas_get_batch_beta_stride

