    !---------------------------------------------
    ! rocblas_snrm2
    !---------------------------------------------
    !>     \brief  BLAS Level 1 API
    !>
    !>     \details
    !>     The nrm2 functions compute the Euclidean norm of a real or complex vector:
    !>
    !>         result := sqrt( x'*x ) for real vectors
    !>         result := sqrt( x**H*x ) for complex vectors
    !>
    !>     @param[in] handle - [rocblas_handle]
    !>               handle to the rocBLAS library context queue.
    !>     @param[in] n - [rocblas_int]
    !>               the number of elements in x.
    !>     @param[in] x - device pointer storing vector x.
    !>     @param[in] incx - [rocblas_int]
    !>               specifies the increment for the elements of y.
    !>     @param[in, out] myResult
    !>               device pointer or host pointer to store the nrm2 product.
    !>               Return value is 0.0 if n, incx<=0.
    function rocblas_snrm2(handle, n, x, incx, myResult) &
       result(snrm2) &
       bind(C, name="rocblas_snrm2")
       import :: c_ptr, c_int, rocblas_status_success
       type(c_ptr), value :: handle
       integer(c_int), value :: n
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       type(c_ptr), value :: myResult
       integer(kind(rocblas_status_success)) :: snrm2
    end function rocblas_snrm2

